@namespace sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Model.FullName" @onchange="e => Update(Model with { FullName = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Model.Email" @onchange="e => Update(Model with { Email = (string?)e.Value ?? string.Empty })" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="validation-error">@EmailError</span>
        }
    </div>
    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Model.Phone" @onchange="e => Update(Model with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address" @onchange="e => Update(Model with { Address = (string?)e.Value ?? string.Empty })"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <p class="validation-error">@ValidationError</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfoModel> OnModelChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task Update(PersonalInfoModel updated)
    {
        EmailError = null;
        await OnModelChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <div class="entry-section">
            <h3>Position @(index + 1)</h3>
            <WorkEntryForm Entry="@Entries[index]"
                           CanRemove="@(Entries.Count > 1)"
                           OnEntryChanged="e => UpdateEntry(index, e)"
                           OnRemove="() => RemoveEntry(index)" />
        </div>
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <p class="validation-error">@ValidationError</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task UpdateEntry(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task RemoveEntry(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries)
        {
            new()
        };
        await OnEntriesChanged.InvokeAsync(list);
    }

