@namespace sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-section">
            <h3>Reference @(index + 1)</h3>
            <ReferenceForm Reference="@References[index]"
                           CanRemove="@(References.Count > 2)"
                           OnReferenceChanged="e => UpdateReference(index, e)"
                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <p class="validation-error">@ValidationError</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnReferencesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task UpdateReference(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task RemoveReference(int index)
    {
        var list = new List<ReferenceModel>(References);
        list.RemoveAt(index);
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<ReferenceModel>(References)
        {
            new()
        };
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (References.Count < 2)
        {
            ValidationError = "At least 2 references are required.";
            return;
        }
        var first = References[0];
        if (string.IsNullOrWhiteSpace(first.Name) || string.IsNullOrWhiteSpace(first.Email))
        {
            ValidationError = "Each reference must have at least a name and email.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

