namespace sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Components.Pages.Apply;

/// <summary>
/// Mutable form models used by the multi-step wizard. These are separate from
/// the immutable domain records to allow two-way binding in the form UI.
/// </summary>
public record PersonalInfoModel
{
    public string FullName { get; init; } = string.Empty;
    public string Email { get; init; } = string.Empty;
    public string Phone { get; init; } = string.Empty;
    public string Address { get; init; } = string.Empty;
}

public record WorkEntryModel
{
    public string Company { get; init; } = string.Empty;
    public string Title { get; init; } = string.Empty;
    public DateTime StartDate { get; init; } = DateTime.Today;
    public DateTime? EndDate { get; init; }
    public bool IsCurrent { get; init; }
    public string Description { get; init; } = string.Empty;
}

public record ReferenceModel
{
    public string Name { get; init; } = string.Empty;
    public string Relationship { get; init; } = string.Empty;
    public string Email { get; init; } = string.Empty;
    public string Phone { get; init; } = string.Empty;
}

@page "/apply"
@namespace sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Components.Pages.Apply
@using sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Models
@using sv_83ded4ae7e7f4d02a4ba2e17087ed63e.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              OnModelChanged="m => personalInfo = m"
                              OnNext="NextFromPersonalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="e => workEntries = e"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="r => references = r"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnCoverLetterChanged="c => coverLetter = c"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="PreviousStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new() };
    private List<ReferenceModel> references = new() { new(), new() };
    private string coverLetter = string.Empty;

    private void NextFromPersonalInfo()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0) currentStep--;
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

